    return B().block(s, I, { eyebrow: 'The access object', tone: 'data', title: 'Every result says what was allowed, and what decided it', paras: ['<code>requested</code> repeats your mode and use. <code>signals</code> lists what we found: robots.txt, page directives, Content Signals, llms.txt, publisher Markdown, licences such as RSL and Creative Commons. <code>decision</code> gives each content type a verdict and the signals that supported, promoted or blocked it.'] }, { el: wrap, text: BOARD.allowed.h + '\n' + BOARD.allowed.p + '\n\n' + BOARD.blocked.h + '\n' + BOARD.blocked.p });
