    const IMG = { og: ['1200 × 630 · 220 KB', 1], sq: ['600 × 600 · 90 KB', 0], big: ['2400 × 1260 · 2.4 MB', 0], none: ['no image', 0] };
    const field = (k, label, rows) => { const w = div(''); w.innerHTML = `<div style="font:500 12px ${GMONO};color:${I.mute};margin-bottom:5px">${label}</div>`; const t = document.createElement(rows ? 'textarea' : 'input'); if (rows) t.rows = rows; t.value = st[k]; t.style.cssText = `width:100%;box-sizing:border-box;padding:9px 11px;border:0;border-radius:8px;box-shadow:inset 0 0 0 1px ${I.line};background:${I.surf};color:${I.ink};font:400 14px/1.45 ${SANS};resize:none;outline-color:${I.pub}`; t.oninput = () => { st[k] = t.value; draw(); }; w.appendChild(t); return w; };
